// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(c.blacklist(actor) == false);

        vm.prank(actor);
        c.getTokens();

        // General rule: any whitelisted caller of getTokens must end up
        // holding a nonzero token balance after a successful distribution.
        assertTrue(c.balanceOf(actor) > 0);
    }
}
